    private final String value;

    private ErrorCode(String value) {
        this.value = value;
    }

    /**
     * @param value the value as the API sends it
     * @return the known constant, or a new instance for a value this SDK version does not know
     */
    public static ErrorCode of(String value) {
        Objects.requireNonNull(value, "value");
        ErrorCode known = registry.get(value);
        return known != null ? known : new ErrorCode(value);
    }

    /**
     * @param data a JSON string
     * @return the value
     */
    public static ErrorCode fromJson(Object data) {
        return of(Wire.string(data));
    }

    /** @return every value this SDK version knows, in the order of the contract */
    public static List<ErrorCode> values() {
        return List.copyOf(registry.values());
    }

    /** @return the value as the API sends it */
    public String value() {
        return value;
    }

    /** @return whether this SDK version knows the value */
    public boolean isKnown() {
        return registry.get(value) == this;
    }

    @Override
    public Object toJson() {
        return value;
    }

    @Override
    public boolean equals(Object other) {
        return other instanceof ErrorCode that && value.equals(that.value);
    }

    @Override
    public int hashCode() {
        return value.hashCode();
    }

    @Override
    public String toString() {
        return value;
    }

    private static Map<String, ErrorCode> index(ErrorCode... values) {
        Map<String, ErrorCode> out = new LinkedHashMap<>();
        for (ErrorCode v : values) {
            out.put(v.value, v);
        }
        return Collections.unmodifiableMap(out);
    }
